        let index = weekday2index(&day);
        self.temperatures[index]
    }

    pub fn set_temperature(&mut self, day: Weekday, temperature: i32) {
        let index = weekday2index(&day);
        self.temperatures[index] = Some(temperature);
    }
}

fn weekday2index(day: &Weekday) -> usize {
    match day {
        Weekday::Monday => 0,
        Weekday::Tuesday => 1,
        Weekday::Wednesday => 2,
        Weekday::Thursday => 3,
        Weekday::Friday => 4,
        Weekday::Saturday => 5,
        Weekday::Sunday => 6,
    }
}

