fn visit(chars: &[char], used: &mut Vec<bool>, path: &mut Vec<char>, out: &mut Vec<String>) {
    if path.len() == chars.len() {
        out.push(path.iter().collect());
        return;
    }
    for index in 0..chars.len() {
        if used[index] {
            continue;
        }
        if index > 0 && chars[index] == chars[index - 1] && !used[index - 1] {
            continue;
        }
        used[index] = true;
        path.push(chars[index]);
        visit(chars, used, path, out);
        path.pop();
        used[index] = false;
    }
}

