fn place(n: usize, row: usize, cols: &mut Vec<bool>, diag: &mut Vec<bool>, anti: &mut Vec<bool>) -> u64 {
    if row == n {
        return 1;
    }
    let mut total = 0;
    for col in 0..n {
        let d = row + col;
        let a = row + n - col;
        if cols[col] || diag[d] || anti[a] {
            continue;
        }
        cols[col] = true;
        diag[d] = true;
        anti[a] = true;
        total += place(n, row + 1, cols, diag, anti);
        cols[col] = false;
        diag[d] = false;
        anti[a] = false;
    }
    total
}

