pub fn solve(input: &str) -> String {
    let mut numbers = input.split_whitespace().filter_map(|t| t.parse::<u64>().ok());
    let (mut a, mut b) = (numbers.next().unwrap_or(0), numbers.next().unwrap_or(0));
    while b != 0 {
        (a, b) = (b, a % b);
    }
    a.to_string()
}
